                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.sales_for_liquid_check as with params as ( select dateadd(day, -1, current_date()) as as_of_date, date_trunc(\'month\', dateadd(day, -1, current_date())) as as_of_month, day(dateadd(day, -1, current_date())) as cutoff_day ), main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger, _airbyte_data:\"Entity\"::STRING AS entity, _airbyte_data:\"Facility\"::STRING AS facility, NULLIF(_airbyte_data:\"GRN Price Without Tax\"::STRING, \'\')::FLOAT AS grn_price_without_tax, NULLIF(_airbyte_data:\"MRP\"::STRING, \'\')::FLOAT AS mrp, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date, TRY_TO_DATE(_airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\') AS original_invoice_date, _airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code, NULLIF(_airbyte_data:\"Quantity\"::STRING, \'\')::INTEGER AS quantity, _airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number, NULLIF(_airbyte_data:\"Sales\"::STRING, \'\')::FLOAT AS sales, NULLIF(_airbyte_data:\"Total\"::STRING, \'\')::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING, _airbyte_data:\"Product SKU Code\"::STRING, _airbyte_data:\"Warehouse Name\"::STRING, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 union all select channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, to_date(Original_Invoice_Date, \'DD-MM-YYYY\') as original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 union all SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING AS channel_ledger, GET(VARIANT_COL, \'Entity\')::STRING AS entity, GET(VARIANT_COL, \'Facility\')::STRING AS facility, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT AS grn_price_without_tax, GET(VARIANT_COL, \'MRP\')::FLOAT AS mrp, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP AS original_created_date, TO_DATE(GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\') as original_invoice_date, GET(VARIANT_COL, \'Product SKU Code\')::STRING AS product_sku_code, GET(VARIANT_COL, \'Quantity\')::INT AS quantity, GET(VARIANT_COL, \'Sale Order Number\')::STRING AS sale_order_number, GET(VARIANT_COL, \'Sales\')::FLOAT AS sales, GET(VARIANT_COL, \'Total\')::FLOAT AS total FROM snitch_db.MAPLEMONK.mis_feb_20260504 union all select channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, to_date(Original_Invoice_Date, \'DD-MM-YYYY\') as original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map as ( select sku_group, cost_price, category from SNITCH_DB.MAPLEMONK.base_product qualify row_number() over (partition by sku_group order by cost_price desc) = 1 ), cat_mp as ( select case when left(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)), \'-\', 0) else UPPER(TRIM(SKUGROUP)) end as sku_group, case when category = \'Jacket\' then \'Jackets\' when category in (\'PYJAMAS\',\'Night Suit & Pyjamas\',\'Joggers & Trackpants\',\'Trackpants\',\'JOGGERS\') then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\', \'Chinos\') then \'Trousers\' else category end as category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over ( partition by case when left(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)), \'-\', 0) else UPPER(TRIM(SKUGROUP)) end order by case when category = \'Jacket\' then \'Jackets\' when category in (\'PYJAMAS\',\'Night Suit & Pyjamas\',\'Joggers & Trackpants\',\'Trackpants\',\'JOGGERS\') then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\', \'Chinos\') then \'Trousers\' else category end asc ) = 1 ), shopify_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code))))) AS sku_group, \'Shopify\' as Channel, sum(quantity)::int as quantity, sum(sales)::int as sales, sum((mrp * quantity))::int as mrp, sum(total)::int as total, sum( coalesce(try_to_number(nullif(regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0) * coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0) )::int as cost_price from main where channel_ledger = \'Snitch\' and entity = \'NEW_INVOICE\' group by 1, 2, 3, 4 ), shopify_net as ( select \"Display Order Number\" as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" = \'Snitch\' group by 1, 2 ), shopify as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, case when ifnull(b.return_qty, 0) > quantity then \'false\' else \'true\' end as flag, sales * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_sales, mrp * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_mrp, total * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_total, cost_price * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_cost_price from shopify_gross a left join shopify_net b on a.order_name = b.order_name and a.sku_group = b.sku_group ), shopify_main as ( select a.date, a.sku_group, b.category, \'Shopify\' Channel, sum(quantity) as quantity, sum(quantity - return_qty) as net_quantity, sum(total) as sales, sum(net_total) as net_sales, sum(mrp - total) as discount, sum(net_mrp - net_total) as net_discount, sum(a.cost_price) as cost_price, sum(net_cost_price) as net_cost_price from shopify a left join cost_price_map b on a.sku_group = b.sku_group group by 1, 2, 3, 4 ), mp_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code))))) AS sku_group, case when channel_ledger in (\'AJIO_SAPL_TAURU\',\'SAPL_AJIO_OMNI\',\'SAPL_AJIO_OMNI_2\') then \'MP_Ajio\' when channel_ledger in (\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\') then \'MP_Amazon\' when channel_ledger in (\'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\') then \'MP_Flipkart_PPMP\' when channel_ledger in (\'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\') then \'MP_Myntra_PPMP\' when channel_ledger in (\'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\',\'NYKAA_FASHION_SAPL_TAURU\',\'NYKAA_FASHION_WH\',\'NYKAA_FASHION_WH2\',\'NYKAA_SAPL_TAURU\') then \'MP_Nykaa\' else \'others\' end as Channel, sum(quantity) as quantity, sum( case when channel_ledger in (\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\',\'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\',\'NYKAA_FASHION_SAPL_TAURU\',\'NYKAA_FASHION_WH\',\'NYKAA_FASHION_WH2\',\'NYKAA_SAPL_TAURU\') then total when channel_ledger in (\'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\') and original_invoice_date >= \'2026-03-26\' then total + quantity * avg_cat_charges when channel_ledger in (\'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\') then total when channel_ledger in (\'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\') then (total / 0.82)::INT when channel_ledger in (\'AJIO_SAPL_TAURU\',\'SAPL_AJIO_OMNI\',\'SAPL_AJIO_OMNI_2\') then (total / 0.68)::INT ELSE SALES END )::int AS SALES, sum( coalesce(try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0) * coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) as MRP, sum( coalesce(try_to_number(nullif(regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0) * coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) as cp from main a left join cost_price_map b on trim(upper(REVERSE(SUBSTRING(REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code))))) = b.sku_group left join snitch_db.maplemonk.AVG_GT_CHARGES c on b.category = c.category where channel_ledger in ( \'AJIO_SAPL_TAURU\',\'SAPL_AJIO_OMNI\',\'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\',\'NYKAA_FASHION_WH\',\'NYKAA_FASHION_WH2\',\'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\' ) group by 1, 2, 3, 4 ), mp_return as ( select \"Display Order Number\" as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" in ( \'AJIO_SAPL_TAURU\',\'SAPL_AJIO_OMNI\',\'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\',\'NYKAA_FASHION_WH\',\'NYKAA_FASHION_WH2\',\'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\' ) group by 1, 2 ), mp_main_pre as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, case when ifnull(b.return_qty, 0) > quantity then \'false\' else \'true\' end as flag, sales * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_sales, mrp * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_mrp, cp * ((quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end) / quantity) as net_cp from mp_gross a left join mp_return b on a.order_name = b.order_name and a.sku_group = b.sku_group ), mp_cat as ( select upper(trim(LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))))) AS sku_group, category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over ( partition by upper(trim(LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))))) order by category desc ) = 1 ), mp_main as ( select a.date, a.sku_group, coalesce(b.category, c.category) as category, Channel, sum(quantity) as quantity, sum(quantity - return_qty) as net_quantity, sum(sales) as sales, sum(net_sales) as net_sales, sum(mrp - sales) as discount, sum(net_mrp - net_sales) as net_discount, sum(cp) as cost_price, sum(net_cp) as net_cost_price from mp_main_pre a left join cost_price_map b on a.sku_group = b.sku_group left join mp_cat c on a.sku_group = c.sku_group group by 1, 2, 3, 4 ), offline_pre as ( select b.order_date::date as date, b.sku_group, coalesce(cp.category, \'others\') as category, \'Store\' as channel, case when marketplace_mapped in ( \'SNITCH - WH - B2B\',\'SNITCH - SNITCH X\',\'SNITCH - WH - M P\',\'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - U.P\',\'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - EMIZA\',\'SNITCH - WH - YELHANKA 2\' ) or b.sku_group like \'cb%\' or doc_prefix in (\'OMS\', \'QCOM\') then 1 else 0 end as filters, sum(b.shipping_quantity)::int as quantity, sum(b.shipping_quantity)::int as net_quantity, sum(b.selling_price)::int as sales, sum(b.selling_price)::int as net_sales, sum(discount)::int as discount, sum(discount)::int as net_discount, (sum(cp.cost_price * b.shipping_quantity))::int as cost_price, (sum(cp.cost_price * b.shipping_quantity))::int as net_cost_price from snitch_db.maplemonk.store_fact_items_offline b left join cost_price_map cp on b.sku_group = cp.sku_group where coalesce(cp.category, \'others\') <> \'others\' group by 1, 2, 3, 4, 5 ), offline_main as ( select date, sku_group, category, \'Offline\' channel, quantity, net_quantity, sales, net_sales, discount, net_discount, cost_price, net_cost_price from offline_pre where filters = 0 ), myntra_sor as ( select TRY_TO_DATE(NULLIF(TRIM(order_created_date::VARCHAR), \'\'), \'YYYYMMDD\') AS date, upper(trim(a.style)) as sku_group, coalesce(b.category, c.category) as category, \'MP_myntra_SOR\' as channel, sum(sales) as quantity, sum(sales) as net_quantity, sum(replace(revenue, \',\', \'\')) as sales, sum(replace(revenue, \',\', \'\')) as net_sales, sum(replace(\"MRP Sales\", \',\', \'\') - replace(revenue, \',\', \'\')) as discount, sum(replace(\"MRP Sales\", \',\', \'\') - replace(revenue, \',\', \'\')) as net_discount, sum(replace(cogs_qty, \',\', \'\')) as cost_price, sum(replace(cogs_qty, \',\', \'\')) as net_cost_price from snitch_db.maplemonk.S3_MYNTRA_B2B_GP a left join cat_mp b on upper(trim(a.style)) = b.sku_group left join mp_cat c on upper(trim(a.style)) = c.sku_group group by 1, 2, 3, 4 ), flipkart_sor as ( select TRY_TO_DATE(NULLIF(TRIM(order_date_key::VARCHAR), \'\'), \'YYYYMMDD\') AS date, upper(trim(a.STYLE)) as sku_group, coalesce(b.category, c.category) as category, \'MP_flipkart_SOR\' as channel, sum(replace(units, \',\', \'\')) as quantity, sum(replace(units, \',\', \'\')) as net_quantity, sum(replace(SP_Qty, \',\', \'\')) as sales, sum(replace(SP_Qty, \',\', \'\')) as net_sales, sum(replace(\"MRP Rev\", \',\', \'\') - replace(SP_QTY_EXCL_GST, \',\', \'\')) as discount, sum(replace(\"MRP Rev\", \',\', \'\') - replace(SP_QTY_EXCL_GST, \',\', \'\')) as net_discount, sum(replace(COGS_UNITS, \',\', \'\')) as cost_price, sum(replace(COGS_UNITS, \',\', \'\')) as net_cost_price from snitch_db.maplemonk.S3_Flipkart_B2B_GP a left join cat_mp b on upper(trim(a.STYLE)) = b.sku_group left join mp_cat c on upper(trim(a.STYLE)) = c.sku_group group by 1, 2, 3, 4 ), slikk as ( select TO_DATE(order_date, \'DD-MM-YYYY\') AS date, upper(trim(a.\"Style \")) as sku_group, coalesce(b.category, c.category) as category, \'MP_slikk\' as channel, sum(total_quantity) as quantity, sum(total_quantity) as net_quantity, sum(total_amount) as sales, sum(total_amount) as net_sales, sum((mrp * total_quantity) - total_amount) as discount, sum((mrp * total_quantity) - total_amount) as net_discount, sum(\"COGSxQty \") as cost_price, sum(\"COGSxQty \") as net_cost_price from snitch_db.maplemonk.google_sheets_slikk a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group left join mp_cat c on upper(trim(a.\"Style \")) = c.sku_group group by 1, 2, 3, 4 ), mp_gross_sor as ( select original_invoice_date as date, sale_order_number as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code))))) AS sku_group, channel_ledger as Channel, sum(quantity) as quantity, sum(total)::int AS SALES, sum( coalesce(try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0) * coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) as MRP, sum( coalesce(try_to_number(nullif(regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0) * coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) as cp from main a left join cost_price_map b on trim(upper(REVERSE(SUBSTRING(REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code))))) = b.sku_group left join snitch_db.maplemonk.AVG_GT_CHARGES c on b.category = c.category where UPPER(channel_ledger) not in ( \'AJIO_SAPL_TAURU\',\'SAPL_AJIO_OMNI\',\'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\',\'NYKAA_FASHION_WH\',\'NYKAA_FASHION_WH2\',\'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\', \'CUSTOM\',\'AMAZON_SAPL_TAURU\',\'B2B CORPORATE CHANNEL\',\'SAPL_WH_TRANSFERS\' ) and UPPER(channel_ledger) not like \'%STORE%\' and UPPER(channel_ledger) not like \'%SNITCH%\' group by 1, 2, 3, 4 ), mp_return_sor as ( select \"Display Order Number\" as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where UPPER(\"Channel Ledger\") not in ( \'AJIO_SAPL_TAURU\',\'SAPL_AJIO_OMNI\',\'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\',\'NYKAA_FASHION_WH\',\'NYKAA_FASHION_WH2\',\'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\', \'CUSTOM\',\'AMAZON_SAPL_TAURU\',\'B2B CORPORATE CHANNEL\',\'SAPL_WH_TRANSFERS\' ) and UPPER(\"Channel Ledger\") not like \'%STORE%\' and UPPER(\"Channel Ledger\") not like \'%SNITCH%\' group by 1, 2 ), mp_main_pre_sor as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, 