\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku_2 a GROUP BY 1 ), sales_raw AS ( SELECT UPPER(TRIM(s.sku_group)) AS sku_group, s.date::DATE AS date, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\' THEN s.quantity ELSE 0 END) AS mp_ppmp_qty, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\' THEN s.sales ELSE 0 END) AS mp_ppmp_sales, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\' THEN s.cost_price ELSE 0 END) AS mp_ppmp_cost, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\' THEN s.net_quantity ELSE 0 END) AS mp_ppmp_net_qty, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\' THEN s.net_sales ELSE 0 END) AS mp_ppmp_net_sales, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\' THEN s.net_cost_price ELSE 0 END) AS mp_ppmp_net_cost, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) LIKE \'%SOR%\' THEN s.quantity ELSE 0 END) AS mp_sor_qty, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) LIKE \'%SOR%\' THEN s.sales ELSE 0 END) AS mp_sor_sales, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) LIKE \'%SOR%\' THEN s.cost_price ELSE 0 END) AS mp_sor_cost, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) LIKE \'%SOR%\' THEN s.net_quantity ELSE 0 END) AS mp_sor_net_qty, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) LIKE \'%SOR%\' THEN s.net_sales ELSE 0 END) AS mp_sor_net_sales, SUM(CASE WHEN UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) LIKE \'%SOR%\' THEN s.net_cost_price ELSE 0 END) AS mp_sor_net_cost, SUM(CASE WHEN UPPER(s.channel) = \'SHOPIFY\' THEN s.quantity ELSE 0 END) AS shopify_qty, SUM(CASE WHEN UPPER(s.channel) = \'SHOPIFY\' THEN s.sales ELSE 0 END) AS shopify_sales, SUM(CASE WHEN UPPER(s.channel) = \'SHOPIFY\' THEN s.cost_price ELSE 0 END) AS shopify_cost, SUM(CASE WHEN UPPER(s.channel) = \'SHOPIFY\' THEN s.net_quantity ELSE 0 END) AS shopify_net_qty, SUM(CASE WHEN UPPER(s.channel) = \'SHOPIFY\' THEN s.net_sales ELSE 0 END) AS shopify_net_sales, SUM(CASE WHEN UPPER(s.channel) = \'SHOPIFY\' THEN s.net_cost_price ELSE 0 END) AS shopify_net_cost FROM snitch_db.maplemonk.sales_for_liquid_check s INNER JOIN liquid_skus l ON UPPER(TRIM(s.sku_group)) = l.sku_group WHERE s.date::DATE >= \'2026-10-01\' GROUP BY 1, 2 ), sku_cat AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(meta_category) AS meta_category FROM snitch_db.maplemonk.sales_for_liquid_check GROUP BY 1 ), hist AS ( SELECT UPPER(TRIM(s.sku_group)) AS sku_group, SUM(IFF(UPPER(s.channel) = \'SHOPIFY\', s.quantity, 0)) AS sh_gq, SUM(IFF(UPPER(s.channel) = \'SHOPIFY\', LEAST(s.net_quantity, s.quantity), 0)) AS sh_nq, SUM(IFF(UPPER(s.channel) = \'SHOPIFY\', s.sales, 0)) AS sh_gs, SUM(IFF(UPPER(s.channel) = \'SHOPIFY\', LEAST(s.net_sales, s.sales), 0)) AS sh_ns, SUM(IFF(UPPER(s.channel) = \'SHOPIFY\', s.cost_price, 0)) AS sh_gc, SUM(IFF(UPPER(s.channel) = \'SHOPIFY\', LEAST(s.net_cost_price, s.cost_price), 0)) AS sh_nc, SUM(IFF(UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\', s.quantity, 0)) AS mp_gq, SUM(IFF(UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\', LEAST(s.net_quantity, s.quantity), 0)) AS mp_nq, SUM(IFF(UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\', s.sales, 0)) AS mp_gs, SUM(IFF(UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\', LEAST(s.net_sales, s.sales), 0)) AS mp_ns, SUM(IFF(UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\', s.cost_price, 0)) AS mp_gc, SUM(IFF(UPPER(s.channel) LIKE \'MP%\' AND UPPER(s.channel) NOT LIKE \'%SOR%\', LEAST(s.net_cost_price, s.cost_price), 0)) AS mp_nc FROM snitch_db.maplemonk.sales_for_liquid_check s WHERE s.date::DATE < DATEADD(day, -10, CURRENT_DATE()) GROUP BY 1 ), cat_hist AS ( SELECT k.meta_category, SUM(h.sh_gq) sh_gq, SUM(h.sh_nq) sh_nq, SUM(h.sh_gs) sh_gs, SUM(h.sh_ns) sh_ns, SUM(h.sh_gc) sh_gc, SUM(h.sh_nc) sh_nc, SUM(h.mp_gq) mp_gq, SUM(h.mp_nq) mp_nq, SUM(h.mp_gs) mp_gs, SUM(h.mp_ns) mp_ns, SUM(h.mp_gc) mp_gc, SUM(h.mp_nc) mp_nc FROM hist h JOIN sku_cat k ON h.sku_group = k.sku_group GROUP BY 1 ), net_ratio AS ( SELECT l.sku_group, COALESCE(LEAST(1, h.sh_nq / NULLIF(h.sh_gq, 0)), LEAST(1, c.sh_nq / NULLIF(c.sh_gq, 0)), 1) AS sh_q, COALESCE(LEAST(1, h.sh_ns / NULLIF(h.sh_gs, 0)), LEAST(1, c.sh_ns / NULLIF(c.sh_gs, 0)), 1) AS sh_s, COALESCE(LEAST(1, h.sh_nc / NULLIF(h.sh_gc, 0)), LEAST(1, c.sh_nc / NULLIF(c.sh_gc, 0)), 1) AS sh_c, COALESCE(LEAST(1, h.mp_nq / NULLIF(h.mp_gq, 0)), LEAST(1, c.mp_nq / NULLIF(c.mp_gq, 0)), 1) AS mp_q, COALESCE(LEAST(1, h.mp_ns / NULLIF(h.mp_gs, 0)), LEAST(1, c.mp_ns / NULLIF(c.mp_gs, 0)), 1) AS mp_s, COALESCE(LEAST(1, h.mp_nc / NULLIF(h.mp_gc, 0)), LEAST(1, c.mp_nc / NULLIF(c.mp_gc, 0)), 1) AS mp_c FROM liquid_skus l LEFT JOIN hist h ON l.sku_group = h.sku_group LEFT JOIN sku_cat k ON l.sku_group = k.sku_group LEFT JOIN cat_hist c ON k.meta_category = c.meta_category ), sales AS ( SELECT r.* REPLACE ( IFF(r.date >= DATEADD(day, -10, CURRENT_DATE()) AND r.shopify_net_qty >= r.shopify_qty, r.shopify_qty * x.sh_q, r.shopify_net_qty) AS shopify_net_qty, IFF(r.date >= DATEADD(day, -10, CURRENT_DATE()) AND r.shopify_net_qty >= r.shopify_qty, r.shopify_sales * x.sh_s, r.shopify_net_sales) AS shopify_net_sales, IFF(r.date >= DATEADD(day, -10, CURRENT_DATE()) AND r.shopify_net_qty >= r.shopify_qty, r.shopify_cost * x.sh_c, r.shopify_net_cost) AS shopify_net_cost, IFF(r.date >= DATEADD(day, -10, CURRENT_DATE()) AND r.mp_ppmp_net_qty >= r.mp_ppmp_qty, r.mp_ppmp_qty * x.mp_q, r.mp_ppmp_net_qty) AS mp_ppmp_net_qty, IFF(r.date >= DATEADD(day, -10, CURRENT_DATE()) AND r.mp_ppmp_net_qty >= r.mp_ppmp_qty, r.mp_ppmp_sales * x.mp_s, r.mp_ppmp_net_sales) AS mp_ppmp_net_sales, IFF(r.date >= DATEADD(day, -10, CURRENT_DATE()) AND r.mp_ppmp_net_qty >= r.mp_ppmp_qty, r.mp_ppmp_cost * x.mp_c, r.mp_ppmp_net_cost) AS mp_ppmp_net_cost ), r.shopify_net_qty AS shopify_actual_net_qty, r.shopify_net_sales AS shopify_actual_net_sales, r.shopify_net_cost AS shopify_actual_net_cost, r.mp_ppmp_net_qty AS mp_ppmp_actual_net_qty, r.mp_ppmp_net_sales AS mp_ppmp_actual_net_sales, r.mp_ppmp_net_cost AS mp_ppmp_actual_net_cost, r.mp_sor_net_qty AS mp_sor_actual_net_qty, r.mp_sor_net_sales AS mp_sor_actual_net_sales, r.mp_sor_net_cost AS mp_sor_actual_net_cost FROM sales_raw r LEFT JOIN net_ratio x ON r.sku_group = x.sku_group ), inv AS ( SELECT UPPER(TRIM(b.sku_group)) AS sku_group, b.date::DATE AS date, SUM(CASE WHEN UPPER(TRIM(b.channels)) = \'WAREHOUSE\' THEN b.inv ELSE 0 END) AS warehouse_inv, SUM(CASE WHEN UPPER(TRIM(b.channels)) LIKE \'%SOR%\' THEN b.inv ELSE 0 END) AS sor_inv, SUM(CASE WHEN UPPER(TRIM(b.channels)) = \'OFFLINE\' THEN b.inv ELSE 0 END) AS offline_inv FROM snitch_db.maplemonk.inv_deep_analysis b INNER JOIN liquid_skus l ON UPPER(TRIM(b.sku_group)) = l.sku_group WHERE b.date::DATE >= \'2026-10-01\' GROUP BY 1, 2 ), base AS ( SELECT sku_group, date FROM sales UNION SELECT sku_group, date FROM inv ), daily AS ( SELECT b.sku_group, b.date, COALESCE(i.warehouse_inv, 0) AS warehouse_inv, COALESCE(i.sor_inv, 0) AS sor_inv, COALESCE(i.offline_inv, 0) AS offline_inv, COALESCE(i.warehouse_inv, 0) + COALESCE(i.sor_inv, 0) + COALESCE(i.offline_inv, 0) AS total_inv, COALESCE(s.shopify_qty, 0) AS shopify_qty, COALESCE(s.mp_ppmp_qty, 0) AS mp_ppmp_qty, COALESCE(s.mp_sor_qty, 0) AS mp_sor_qty, COALESCE(s.shopify_sales, 0) AS shopify_sales, COALESCE(s.mp_ppmp_sales, 0) AS mp_ppmp_sales, COALESCE(s.mp_sor_sales, 0) AS mp_sor_sales, COALESCE(s.shopify_cost, 0) AS shopify_cost, COALESCE(s.mp_ppmp_cost, 0) AS mp_ppmp_cost, COALESCE(s.mp_sor_cost, 0) AS mp_sor_cost, COALESCE(s.shopify_net_qty, 0) AS shopify_net_qty, COALESCE(s.mp_ppmp_net_qty, 0) AS mp_ppmp_net_qty, COALESCE(s.mp_sor_net_qty, 0) AS mp_sor_net_qty, COALESCE(s.shopify_net_sales, 0) AS shopify_net_sales, COALESCE(s.mp_ppmp_net_sales, 0) AS mp_ppmp_net_sales, COALESCE(s.mp_sor_net_sales, 0) AS mp_sor_net_sales, COALESCE(s.shopify_net_cost, 0) AS shopify_net_cost, COALESCE(s.mp_ppmp_net_cost, 0) AS mp_ppmp_net_cost, COALESCE(s.mp_sor_net_cost, 0) AS mp_sor_net_cost, COALESCE(s.shopify_actual_net_qty, 0) AS shopify_actual_net_qty, COALESCE(s.shopify_actual_net_sales, 0) AS shopify_actual_net_sales, COALESCE(s.shopify_actual_net_cost, 0) AS shopify_actual_net_cost, COALESCE(s.mp_ppmp_actual_net_qty, 0) AS mp_ppmp_actual_net_qty, COALESCE(s.mp_ppmp_actual_net_sales, 0) AS mp_ppmp_actual_net_sales, COALESCE(s.mp_ppmp_actual_net_cost, 0) AS mp_ppmp_actual_net_cost, COALESCE(s.mp_sor_actual_net_qty, 0) AS mp_sor_actual_net_qty, COALESCE(s.mp_sor_actual_net_sales, 0) AS mp_sor_actual_net_sales, COALESCE(s.mp_sor_actual_net_cost, 0) AS mp_sor_actual_net_cost FROM base b LEFT JOIN sales s ON b.sku_group = s.sku_group AND b.date = s.date LEFT JOIN inv i ON b.sku_group = i.sku_group AND b.date = i.date ), cum AS ( SELECT *, DATEDIFF(\'day\', \'2026-10-01\', date) + 1 AS days_since_oct_1, SUM(shopify_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_qty, SUM(mp_ppmp_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_qty, SUM(mp_sor_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_qty, SUM(shopify_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_sales, SUM(mp_ppmp_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_sales, SUM(mp_sor_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_sales, SUM(shopify_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_cost, SUM(mp_ppmp_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_cost, SUM(mp_sor_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_cost, SUM(shopify_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_net_qty, SUM(mp_ppmp_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_net_qty, SUM(mp_sor_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_net_qty, SUM(shopify_net_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_net_sales, SUM(mp_ppmp_net_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_net_sales, SUM(mp_sor_net_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_net_sales, SUM(shopify_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_net_cost, SUM(mp_ppmp_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_net_cost, SUM(mp_sor_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_net_cost, SUM(shopify_sales - shopify_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_margin, SUM(mp_ppmp_sales - mp_ppmp_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_margin, SUM(mp_sor_sales - mp_sor_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_margin, SUM(shopify_net_sales - shopify_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_net_margin, SUM(mp_ppmp_net_sales - mp_ppmp_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_net_margin, SUM(mp_sor_net_sales - mp_sor_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_net_margin, SUM(shopify_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) / NULLIF(DATEDIFF(\'day\', \'2026-10-01\', date) + 1, 0) AS cum_shopify_net_ros, SUM(mp_ppmp_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) / NULLIF(DATEDIFF(\'day\', \'2026-10-01\', date) + 1, 0) AS cum_mp_ppmp_net_ros, SUM(mp_sor_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) / NULLIF(DATEDIFF(\'day\', \'2026-10-01\', date) + 1, 0) AS cum_mp_sor_net_ros, SUM(shopify_actual_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_actual_net_qty, SUM(mp_ppmp_actual_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_actual_net_qty, SUM(mp_sor_actual_net_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_actual_net_qty, SUM(shopify_actual_net_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_actual_net_sales, SUM(mp_ppmp_actual_net_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_actual_net_sales, SUM(mp_sor_actual_net_sales) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_actual_net_sales, SUM(shopify_actual_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_shopify_actual_net_cost, SUM(mp_ppmp_actual_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_ppmp_actual_net_cost, SUM(mp_sor_actual_net_cost) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_mp_sor_actual_net_cost FROM daily ) SELECT c.date, c.sku_group, COALESCE(m2.l1_category, m1.l1_category) AS l1_category, COALESCE(m2.category, m1.category) AS category, COALESCE(m2.meta1, m1.meta1) AS meta1, COALESCE(m2.meta2, m1.meta2) AS meta2, COALESCE(m2.meta3, m1.meta3) AS meta3, c.warehouse_inv, c.sor_inv, c.offline_inv, c.total_inv, c.cum_shopify_qty / NULLIF(c.days_since_oct_1, 0) AS shopify_ros, c.cum_mp_ppmp_qty / NULLIF(c.days_since_oct_1, 0) AS mp_ppmp_ros, c.cum_mp_sor_qty / NULLIF(c.days_since_oct_1, 0) AS mp_sor_ros, c.cum_shopify_sales, c.cum_mp_ppmp_sales, c.cum_mp_sor_sales, c.cum_shopify_sales - c.cum_shopify_cost AS shopify_margin, c.cum_mp_ppmp_sales - c.cum_mp_ppmp_cost AS mp_ppmp_margin, c.cum_mp_sor_sales - c.cum_mp_sor_cost AS mp_sor_margin, 100 * (c.cum_shopify_sales - c.cum_shopify_cost) / NULLIF(c.cum_shopify_sales, 0) AS shopify_gp_pct, 100 * (c.cum_mp_ppmp_sales - c.cum_mp_ppmp_cost) / NULLIF(c.cum_mp_ppmp_sales, 0) AS mp_ppmp_gp_pct, 100 * (c.cum_mp_sor_sales - c.cum_mp_sor_cost) / NULLIF(c.cum_mp_sor_sales, 0) AS mp_sor_gp_pct, 100 * (c.cum_shopify_sales - c.cum_shopify_net_sales) / NULLIF(c.cum_shopify_sales, 0) AS shopify_returns_pct, 100 * (c.cum_mp_ppmp_sales - c.cum_mp_ppmp_net_sales) / NULLIF(c.cum_mp_ppmp_sales, 0) AS mp_ppmp_returns_pct, 100 * (c.cum_mp_sor_sales - c.cum_mp_sor_net_sales) / NULLIF(c.cum_mp_sor_sales, 0) AS mp_sor_returns_pct, c.cum_shopify_net_qty, c.cum_mp_ppmp_net_qty, c.cum_mp_sor_net_qty, c.cum_shopify_net_sales, c.cum_mp_ppmp_net_sales, c.cum_mp_sor_net_sales, c.cum_shopify_net_sales - c.cum_shopify_net_cost AS shopify_net_margin, c.cum_mp_ppmp_net_sales - c.cum_mp_ppmp_net_cost AS mp_ppmp_net_margin, c.cum_mp_sor_net_sales - c.cum_mp_sor_net_cost AS mp_sor_net_margin, 100 * (c.cum_shopify_net_sales - c.cum_shopify_net_cost) / NULLIF(c.cum_shopify_net_sales, 0) AS shopify_net_gp_pct, 100 * (c.cum_mp_ppmp_net_sales - c.cum_mp_ppmp_net_cost) / NULLIF(c.cum_mp_ppmp_net_sales, 0) AS mp_ppmp_net_gp_pct, 100 * (c.cum_mp_sor_net_sales - c.cum_mp_sor_net_cost) / NULLIF(c.cum_mp_sor_net_sales, 0) AS mp_sor_net_gp_pct, c.cum_shopify_margin, c.cum_mp_ppmp_margin, c.cum_mp_sor_margin, c.cum_shopify_net_margin, c.cum_mp_ppmp_net_margin, c.cum_mp_sor_net_margin, c.cum_shopify_net_qty / NULLIF(c.days_since_oct_1, 0) AS shopify_net_ros, c.cum_mp_ppmp_net_qty / NULLIF(c.days_since_oct_1, 0) AS mp_ppmp_net_ros, c.cum_mp_sor_net_qty / NULLIF(c.days_since_oct_1, 0) AS mp_sor_net_ros, c.cum_shopify_actual_net_qty, c.cum_mp_ppmp_actual_net_qty, c.cum_mp_sor_actual_net_qty, c.cum_shopify_actual_net_sales, c.cum_mp_ppmp_actual_net_sales, c.cum_mp_sor_actual_net_sales, c.cum_shopify_actual_net_sales - c.cum_shopify_actual_net_cost AS shopify_actual_net_margin, c.cum_mp_ppmp_actual_net_sales - c.cum_mp_ppmp_actual_net_cost AS mp_ppmp_actual_net_margin, c.cum_mp_sor_actual_net_sales - c.cum_mp_sor_actual_net_cost AS mp_sor_actual_net_margin, 100 * (c.cum_shopify_actual_net_sales - c.cum_shopify_actual_net_cost) / NULLIF(c.cum_shopify_actual_net_sales, 0) AS shopify_actual_net_gp_pct, 100 * (c.cum_mp_ppmp_actual_net_sales - c.cum_mp_ppmp_actual_net_cost) / NULLIF(c.cum_mp_ppmp_actual_net_sales, 0) AS mp_ppmp_actual_net_gp_pct, 100 * (c.cum_mp_sor_actual_net_sales - c.cum_mp_sor_actual_net_cost) / NULLIF(c.cum_mp_sor_actual_net_sales, 0) AS mp_sor_actual_net_gp_pct, 100 * (c.cum_shopify_sales - c.cum_shopify_actual_net_sales) / NULLIF(c.cum_shopify_sales, 0) AS shopify_actual_returns_pct, 100 * (c.cum_mp_ppmp_sales - c.cum_mp_ppmp_actual_net_sales) / NULLIF(c.cum_mp_ppmp_sales, 0) AS mp_ppmp_actual_returns_pct, 100 * (c.cum_mp_sor_sales - c.cum_mp_sor_actual_net_sales) / NULLIF(c.cum_mp_sor_sales, 0) AS mp_sor_actual_returns_pct, c.cum_shopify_actual_net_qty / NULLIF(c.days_since_oct_1, 0) AS shopify_actual_net_ros, c.cum_mp_ppmp_actual_net_qty / NULLIF(c.days_since_oct_1, 0) AS mp_ppmp_actual_net_ros, c.cum_mp_sor_actual_net_qty / NULLIF(c.days_since_oct_1, 0) AS mp_sor_actual_net_ros, c.cum_shopify_qty AS cum_shopify_gross_qty, c.cum_mp_ppmp_qty AS cum_mp_ppmp_gross_qty, c.cum_mp_sor_qty AS cum_mp_sor_gross_qty, c.cum_shopify_qty + c.cum_mp_ppmp_qty + c.cum_mp_sor_qty AS cum_total_gross_qty, c.cum_shopify_cost AS cum_shopify_gross_cost, c.cum_mp_ppmp_cost AS cum_mp_ppmp_gross_cost, c.cum_mp_sor_cost AS cum_mp_sor_gross_cost FROM cum c LEFT JOIN meta_map m1 ON UPPER( IFF( UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(c.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(c.sku_group, \' \', \'\'), \'-.*$\', \'\') ) ) = m1.sku_group_clean LEFT JOIN meta_map_2 m2 ON UPPER(TRIM(c.sku_group)) = UPPER(TRIM(m2.sku_group)) ORDER BY c.sku_group, c.date;",
                    "transaction": true
                }
            ) }}
